--- a/src/cache/store.rs
+++ b/src/cache/store.rs
@@ -3,7 +3,9 @@
 use anyhow::{Context, Result};
 use sha2::{Digest, Sha256};
 use std::fs;
+use std::io::Write;
 use std::path::{Path, PathBuf};
+use tempfile::NamedTempFile;

 use super::entry::CacheEntry;

@@ -45,6 +47,10 @@ impl CacheStore {
     }

     /// Store content and return a cache entry.
+    ///
+    /// Writes are atomic: content and metadata are written to temporary
+    /// files first, then renamed into place. If any step fails, the
+    /// previous cache entry (if any) remains intact.
     pub fn store(
         &self,
         source_id: &str,
@@ -55,12 +61,32 @@ impl CacheStore {
         self.ensure_dir()?;

         let content_path = self.content_path(source_id, template_name);
-        fs::write(&content_path, content)?;
+        let meta_path = self.metadata_path(source_id, template_name);

         let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
             .with_size(content.len() as u64);
-
-        self.save_metadata(&entry)?;
+        let json = serde_json::to_string_pretty(&entry)?;
+
+        // Write both files to temporaries in the same directory, then
+        // rename. rename(2) is atomic on the same filesystem, so readers
+        // always see either the old pair or the new pair.
+        let mut tmp_content = NamedTempFile::new_in(&self.root)
+            .context("Failed to create temp file for cache content")?;
+        tmp_content.write_all(content.as_bytes())?;
+
+        let mut tmp_meta = NamedTempFile::new_in(&self.root)
+            .context("Failed to create temp file for cache metadata")?;
+        tmp_meta.write_all(json.as_bytes())?;
+
+        // Persist renames the temp file to the target path atomically.
+        tmp_content
+            .persist(&content_path)
+            .map_err(|e| e.error)
+            .context("Failed to persist cache content")?;
+        tmp_meta
+            .persist(&meta_path)
+            .map_err(|e| e.error)
+            .context("Failed to persist cache metadata")?;

         Ok(entry)
     }
@@ -89,11 +115,18 @@ impl CacheStore {
         })
     }

-    /// Save entry metadata.
+    /// Save entry metadata atomically via temp-file-then-rename.
     fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
+        self.ensure_dir()?;
         let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
         let json = serde_json::to_string_pretty(entry)?;
-        fs::write(&meta_path, json)?;
+
+        let mut tmp = NamedTempFile::new_in(&self.root)
+            .context("Failed to create temp file for cache metadata")?;
+        tmp.write_all(json.as_bytes())?;
+        tmp.persist(&meta_path)
+            .map_err(|e| e.error)
+            .context("Failed to persist cache metadata")?;
         Ok(())
     }

@@ -309,4 +342,109 @@ mod tests {

         assert_ne!(path1, path2);
     }
+
+    #[test]
+    fn concurrent_writes_to_same_key_never_corrupt() {
+        use std::sync::Arc;
+        use std::thread;
+
+        let temp = TempDir::new().unwrap();
+        let store = Arc::new(CacheStore::new(temp.path()));
+
+        let handles: Vec<_> = (0..10)
+            .map(|i| {
+                let store = Arc::clone(&store);
+                thread::spawn(move || {
+                    let content = format!("content-from-thread-{}", i);
+                    store
+                        .store("http:test", "shared-template", &content, 3600)
+                        .unwrap();
+                })
+            })
+            .collect();
+
+        for h in handles {
+            h.join().unwrap();
+        }
+
+        // After all writes, the entry must be loadable and consistent.
+        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
+        let content = store.read_content(&entry).unwrap();
+
+        assert!(content.starts_with("content-from-thread-"));
+        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
+        assert_eq!(entry.source_id, "http:test");
+        assert_eq!(entry.template_name, "shared-template");
+    }
+
+    #[test]
+    fn concurrent_writes_to_different_keys_all_succeed() {
+        use std::sync::Arc;
+        use std::thread;
+
+        let temp = TempDir::new().unwrap();
+        let store = Arc::new(CacheStore::new(temp.path()));
+
+        let handles: Vec<_> = (0..10)
+            .map(|i| {
+                let store = Arc::clone(&store);
+                thread::spawn(move || {
+                    let name = format!("template-{}", i);
+                    let content = format!("content-{}", i);
+                    store.store("http:test", &name, &content, 3600).unwrap();
+                })
+            })
+            .collect();
+
+        for h in handles {
+            h.join().unwrap();
+        }
+
+        let entries = store.list().unwrap();
+        assert_eq!(entries.len(), 10);
+
+        for i in 0..10 {
+            let name = format!("template-{}", i);
+            let expected_content = format!("content-{}", i);
+            let entry = store.load("http:test", &name).unwrap().unwrap();
+            let content = store.read_content(&entry).unwrap();
+            assert_eq!(content, expected_content);
+            assert_eq!(entry.metadata.size_bytes, expected_content.len() as u64);
+        }
+    }
+
+    #[test]
+    fn store_failure_preserves_original_entry() {
+        let temp = TempDir::new().unwrap();
+        let store = CacheStore::new(temp.path());
+
+        // Store an initial valid entry.
+        store
+            .store("http:test", "template", "original", 3600)
+            .unwrap();
+
+        // Make the cache directory read-only so temp files cannot be
+        // created, simulating a disk-full or permissions failure.
+        let mut perms = fs::metadata(temp.path()).unwrap().permissions();
+        perms.set_readonly(true);
+        fs::set_permissions(temp.path(), perms.clone()).unwrap();
+
+        // Attempt a second store — should fail because no temp file can
+        // be created.
+        let result = store.store("http:test", "template", "new-content", 3600);
+        assert!(result.is_err());
+
+        // Restore permissions for cleanup and reading.
+        #[allow(clippy::permissions_set_readonly_false)]
+        {
+            perms.set_readonly(false);
+        }
+        fs::set_permissions(temp.path(), perms).unwrap();
+
+        // The original entry must be fully intact.
+        let entry = store.load("http:test", "template").unwrap().unwrap();
+        let content = store.read_content(&entry).unwrap();
+        assert_eq!(content, "original");
+        assert_eq!(entry.metadata.size_bytes, "original".len() as u64);
+    }
 }

